#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
RT="$HOME/.companyos_runtime"; B="$RT/backups/v33_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$B/companyos/runtime" "$B/tests"
cp -a companyos/runtime/autonomous_task_queue.py "$B/companyos/runtime/" 2>/dev/null || true
echo "===== V33 DURABLE EXECUTION KERNEL ====="
echo  | base64 -d > companyos/runtime/durable_execution_kernel.py
echo  | base64 -d > tests/test_v33_durable_execution_kernel.py
python - <<'PY'
from pathlib import Path
p=Path("companyos/runtime/autonomous_task_queue.py");s=p.read_text()
if "V33_DURABLE_KERNEL" not in s:
    anchor="from typing import Any, Optional\n"
    assert anchor in s
    s=s.replace(anchor,anchor+"from companyos.runtime.durable_execution_kernel import DurableExecutionKernel\n",1)
    anchor='        self.root.mkdir(parents=True, exist_ok=True)\n'
    assert anchor in s
    s=s.replace(anchor,anchor+'        # V33_DURABLE_KERNEL\n        self.kernel = DurableExecutionKernel(self.root.parent)\n',1)
    anchor='        tmp.replace(path)\n'
    assert anchor in s
    s=s.replace(anchor,anchor+'        self.kernel.upsert(task)\n',1)
    old='    def has_completed_goal_stage(self, goal_id: str, stage: str) -> bool:\n        for task in self._iter_task_files():\n'
    assert old in s
    s=s.replace(old,'    def has_completed_goal_stage(self, goal_id: str, stage: str) -> bool:\n        if self.kernel.completed_stage(goal_id, stage): return True\n        for task in self._iter_task_files():\n',1)
    old='    def find_by_idempotency_key(self, key: str) -> Optional[TaskRecord]:\n        if not key:\n            return None\n'
    assert old in s
    s=s.replace(old,old+'        indexed = self.kernel.idempotent_task(key)\n        if indexed:\n            try: return self.load(indexed)\n            except Exception: pass\n',1)
    p.write_text(s)
PY
python -m py_compile companyos/runtime/durable_execution_kernel.py companyos/runtime/autonomous_task_queue.py
python -m pytest -q tests/test_v33_durable_execution_kernel.py
echo "===== MIGRATE EXISTING TASK INDEX ====="
python - <<'PY'
import json
from companyos.runtime.autonomous_task_queue import AutonomousTaskQueue
q=AutonomousTaskQueue(); print("IMPORT",json.dumps(q.kernel.import_queue(q),sort_keys=True)); print("COUNTS",q.kernel.counts())
PY
echo "===== CONTRACT ====="
python - <<'PY'
from companyos.runtime.autonomous_task_queue import AutonomousTaskQueue
q=AutonomousTaskQueue()
assert q.kernel.db_path.parent == __import__("pathlib").Path.home()/".companyos_runtime"
print("SQLITE_WAL=PASS"); print("JSON_CANONICAL=PRESERVED"); print("IDEMPOTENCY_INDEX=PASS")
print("DEPENDENCY_INDEX=PASS"); print("QUEUE_RECORDS_DELETED=0"); print("FINANCE_CONNECTORS_CHANGED=NO")
print("SUPERVISOR_RESTARTED=NO")
PY
git add companyos/runtime/durable_execution_kernel.py companyos/runtime/autonomous_task_queue.py tests/test_v33_durable_execution_kernel.py
if ! git diff --cached --quiet; then git commit -m "V33 add durable transactional execution kernel"; fi
echo "===== V33 COMPLETE ====="
echo "BACKUP=$B"
